-- Philippine government position catalog
-- Source: DBM Index of Occupational Services, Occupational Groups, Classes and Salary Grades, Volume II.
-- Generated by scripts/build_government_positions_seed.php; safe to run repeatedly.

SET NAMES utf8mb4;
START TRANSACTION;

CREATE TEMPORARY TABLE government_position_seed (
    title VARCHAR(150) NOT NULL PRIMARY KEY,
    salary_grade VARCHAR(10) NOT NULL
) ENGINE=InnoDB;







SELECT seed.title, seed.salary_grade
FROM government_position_seed seed
LEFT JOIN positions existing ON LOWER(TRIM(existing.title)) = LOWER(TRIM(seed.title))
WHERE existing.id IS NULL;

DROP TEMPORARY TABLE government_position_seed;
COMMIT;
